import { scoreItem, decideSurface } from '../../src/utils/flow-items';
export function rankDemo(relevance: number, mode: 'working'|'settling'|'flow'|'stuck'|'away') {
  const now=1_000_000;
  const paragraph='The night bus changed how nurses reached the hospital.';
  const items=[{id:'comment',kind:'comment' as const,title:'A fresh comment',body:'',anchors:[paragraph],createdAt:now,relevance:0.6},{id:'source',kind:'source' as const,title:'A fresh source',body:'',anchors:[paragraph],createdAt:now,relevance}];
  const context={mode,cursorText:paragraph,dismissed:new Set<string>(),shown:new Set<string>(),weight:()=>1,now};
  const decision=decideSurface(items,context);
  return items.map(item=>({title:item.title,score:scoreItem(item,context),visible:decision.visible.some(x=>x.id===item.id),reason:decision.reasons[item.id]})).sort((a,b)=>b.score-a.score);
}

