const branches=[
 ['Cadence → attention state (exact precedence)','state',`<p>Defaults can adapt after sufficient local history. The tree is evaluated once a second when enabled and visible.</p><ol><li>No edit samples → <b>working</b>.</li><li>No edits for 180 seconds → <b>away</b>.</li><li>Reaching for the room → <b>working</b>.</li><li>Already in flow → remain <b>flow</b> until a 25-second pause, then <b>working</b>. Heavy deletion alone does not exit flow.</li><li>Pause ≥ 18 seconds and recent churn ≥ 0.40 → <b>stuck</b>. The optional struggle input is not wired into this caller.</li><li>Previously stuck and pause ≥ 4 seconds → remain <b>stuck</b>.</li><li>Pause ≤ 4 seconds, deletion share ≤ 0.30, active-second share ≥ 0.45 → <b>flow</b> at 90 seconds, or <b>settling</b> at 30 seconds.</li><li>Previously settling, pause ≤ 4 seconds, run ≥ 30 seconds → remain <b>settling</b>.</li><li>Otherwise → <b>working</b>.</li></ol><p>New flow requests pass through the optional Jev gate described above. Inter-edit gaps of at most 4 seconds define the contiguous run.</p>`],
 ['Candidate gathering → semantic gates → fallbacks','candidates',`<p>Gather during working or stuck after a 1.5-second pause, with a paragraph ≥ 60 characters. Stuck transitions force a gather. The same first 200 characters plus mode are skipped; otherwise gathers in the same mode are at least 20 seconds apart.</p><ul><li><b>You wrote / echo:</b> TF-IDF proposes earlier passages; Jev relevance ≥ 0.55 accepts. Missing answer falls back to similarity ≥ 0.30.</li><li><b>Dossier shelf:</b> local references; Jev ≥ 0.55 accepts. Missing answer falls back to similarity ≥ 0.35.</li><li><b>Book / album / song / film:</b> local title candidates; Jev medium choice plus helpfulness ≥ 0.50. No answer means no new work card. A missing cover can leave a title-only card.</li><li><b>Charter:</b> first six eligible standards; Jev breach ≥ 0.70. No answer means no breach card.</li><li><b>A way in:</b> local stuck plus unresolved-passage ≥ 0.60; model chooses fixed prompt. Only the no-client case permits the strong-churn local fallback.</li><li><b>Amendment:</b> approximately 300 net-added words, ≥ 600 characters of prose, and two successive dossier-fit readings below 0.30 for a field. Applying a change remains explicit.</li><li><b>Comments, persona notes, incoming sources:</b> ingested from their existing producers with no additional judgement here.</li></ul>`],
 ['Final ranking → suppression → manual overrides','ranking',`<p>Base weights: way-in <b>0.95</b>; comment <b>0.90</b>; persona note <b>0.75</b>; charter <b>0.70</b>; amendment <b>0.65</b>; source and echo <b>0.55</b>; work <b>0.50</b>; shelf <b>0.45</b>.</p><p>Freshness = 0.6 + 0.4 × exp(−ageMinutes / 20). Default relevance = 0.60. Anchor overlap is lexical. The optional 0.15 viewport bonus is not supplied by the conductor.</p><ol><li>Remove dismissed items; hold way-in unless stuck and anchor overlap &gt; 0.30.</li><li>Sort by the fixed formula shown below.</li><li><b>Flow:</b> zero ordinary cards.</li><li><b>Settling / away:</b> keep items whose IDs have been shown before. That set is cumulative for the mounted session.</li><li><b>Stuck:</b> prefer way-in, then an overlapping item, then the highest-ranked item. Include linked items.</li><li><b>Working:</b> top three. There is no general minimum score.</li></ol><p>Manual reveal and hover-peek can exceed these limits. The narrow-screen dock may show only the first card. Dismissed IDs reset on remount, although dismissal counts persist.</p>`],
 ['Struggle tools and Quick Review: parallel producers','struggle',`<p>These run beside the conductor and do not consult its FlowMode in their run functions. Visibility and CSS can still hide their surfaces.</p><p><b>Struggle:</b> track versions, deletions, undo, split/join changes and hedge flips → local score ≥ 0.50 → Jev tool choice → seed with code → optionally fill with prose. On judgement failure, local strength ≥ 0.60 can open a tentative tool. Deliberate tool opening bypasses struggle classification.</p><p><b>Quick Review:</b> 650 ms pause + paragraph ≥ 80 characters + client → Jev five-way issue choice → fixed category copy. It fails closed if judgement is unavailable.</p>`],
 ['Background room, full-draft review, and research','background',`<ul><li><b>Background room:</b> 500 net new words, 120 seconds idle, ≥ 500 total words, ≥ 5 minutes between passes, at most 8 per session. Reuse exact matching cached Jev triage when available; otherwise process new material without that gate. A prose model generates notes; Jev can review their quality.</li><li><b>Whole-draft review:</b> saved draft event, ≥ 2.5-second pause, ≥ 30 seconds since last start, ≥ 500 words, enabled/online/client. Jev supplies rubric and passage findings; code assembles their presentation. Opening 40,000 characters and up to 12 passages bound this review.</li><li><b>Background research:</b> 45-second debounce, ≥ 120 characters, configured prose provider, at most five targets per pass and 25 background bibliography entries. Prose extraction → selected search backend → arithmetic result ordering.</li></ul>`],
 ['Settings, retries, and personalization','profile',`<ul><li><b>Automatic review + Automatic focus</b> both gate the whole conductor. Margin tools has a separate switch. Cover lookups gates metadata fetching.</li><li><b>Shared Jev budget:</b> at most 12 calls in 60 seconds across pause-driven callers; failures back off callers for 30 seconds.</li><li><b>After 12 pauses:</b> stuck pause = 2 × pause P75, clamped 12–60 seconds. Exit pause = 1.5 × pause P90, clamped 15–45 seconds.</li><li><b>After five flow entries:</b> flow threshold = median entry run, clamped 60–240 seconds; settling is one third.</li><li><b>Kind weight:</b> clamp(2 × (engaged + 1) / (engaged + dismissed + 2), 0.2, 1.8). Shown counts do not enter that formula.</li><li><b>Retry gaps:</b> some candidates are marked asked before success; a budget skip can prevent another attempt during the session. The archive index is built once per conductor lifetime.</li></ul>`]
];

const cards=[
 {id:'alternatives',name:'Three ways forward',hint:'A useful successor to Sentence Lab',title:'Keep the meaning. Change the approach.',intent:'After repeated revision, make the differences between alternatives visible. Offer the writer a choice they can use immediately.',passage:'The night bus was something that had a significant effect on the way Mara was able to get to work.',cardTitle:'Which version sounds like you?',kind:'Three ways forward',options:[['More direct','The night bus changed Mara’s journey to work.'],['Start with the person','For Mara, the night bus changed the journey to work.'],['Start with the change','Mara’s journey to work changed when the night bus arrived.']],signal:'Three rewrites of the same sentence, or an explicit selection. Offer after a pause; let the writer ask sooner.',available:'Actual previous attempts, surrounding prose, goal, audience, tone; variant generation and guarded apply/undo already exist.',needed:'Label the rhetorical difference, check meaning preservation, show a diff, and let the writer edit before applying.',success:'The writer chooses or adapts a useful line, then resumes writing. Ask whether the meaning and voice survived.'},
 {id:'connections',name:'Connect these thoughts',hint:'Reveal missing structure',title:'One suggestion, grounded in three passages.',intent:'Surface a relationship among passages and explain why it matters. The writer should see the exact evidence for the suggestion.',passage:'“The council measured success in tickets sold.”\n\n“The real change was who could afford to keep a job.”',cardTitle:'You are measuring two different things.',kind:'Structural connection',options:[['Make the distinction','Ticket sales count journeys; they do not establish whether the service helped people keep a job.'],['Turn it into a question','What would show whether those extra journeys made a difference to keeping a job?']],signal:'On sentence hover or explicit structure review; an ambient offer can wait until a paragraph boundary.',available:'Multiple literal anchors per card, paragraph candidates, full draft, dossier and hover-link rendering.',needed:'Stable sentence anchors; supported / contradicts / develops / missing bridge relationships; judgement of evidence; multi-passage suggestion generation.',success:'The writer understands the relationship and can accept, change, or reject it. No rearrangement without an explicit preview.'},
 {id:'evidence',name:'Evidence with limits',hint:'A useful source, not just a link',title:'Show what the source actually establishes.',intent:'Place the claim beside an exact source excerpt and explain the boundary. A search result’s title is not enough.',passage:'The new night bus cut missed hospital shifts by half.',cardTitle:'What would support this claim?',kind:'Evidence check',options:[['Find the underlying numbers','Look for shift attendance before and after the route change.'],['Narrow the claim','The new night bus offered another way to reach the hospital.'],['Keep the uncertainty visible','Did the new night bus reduce missed shifts? [source needed]']],signal:'A selected factual claim, a source request, or a verified evidence gap. Do not equate every number with an error.',available:'Claim targets, bibliography, source URLs/snippets, saved claim–source pairs, search tools.',needed:'Retrieve and verify the exact source excerpt; label supports / qualifies / disagrees / unassessed; distinguish snippets from full-source checks.',success:'The writer cites a real passage, narrows the claim, or records an unresolved question. This demo contains no fabricated citation.'},
 {id:'shape',name:'Show the shape',hint:'A visual cue for the argument',title:'Make the missing link visible.',intent:'Render a small argument map, timeline, or comparison when it helps the writer inspect the logic. Keep every node tied to text.',passage:'The bus ran before the first shift. More people could reach the hospital. Missed shifts fell.',cardTitle:'Is this the causal chain you mean?',kind:'Argument sketch',diagram:true,options:[['Add the missing test','What evidence links the new journey option to attendance?'],['State the limit','The timing fits, but these observations alone do not establish the cause.']],signal:'On request, or after a confirmed unclear relationship. Prefer a small diagram of one argument over a whole-document hairball.',available:'Passages, entities, claims, dossier purpose and retrieved sources.',needed:'A constrained diagram schema, anchored labels, editable relationships and an equivalent accessible text view.',success:'The writer spots the uncertain edge, supplies evidence, or changes the argument. A neat diagram does not validate a claim.'},
 {id:'word',name:'Find the exact word',hint:'A phrase choice in context',title:'Offer distinctions a thesaurus misses.',intent:'Help with a repeatedly changed word or selected phrase by showing each alternative in the sentence with its change in meaning.',passage:'Mara walked through the empty ward.',cardTitle:'What kind of movement do you mean?',kind:'Word choice',options:[['Plain and neutral','Mara walked through the empty ward.'],['Hurried, without running','Mara hurried through the empty ward.'],['Quiet or unobtrusive','Mara slipped through the empty ward.']],signal:'A selected word or repeated changes to the same phrase. Ask the writer about meaning instead of inferring an emotion.',available:'Selection, sentence, previous versions, surrounding prose, tone and audience.',needed:'Stable phrase spans, lexical context checks, short explanations of register, and replacement of only the selected span.',success:'The writer finds the intended meaning with less disruption. Different movement or emotion must be labelled as a meaning change.'},
 {id:'recover',name:'Recover a useful detail',hint:'A purposeful successor to “You wrote”',title:'Bring back the detail that did work.',intent:'Use previous versions to show something specific that disappeared. Make its relevance explicit instead of resurfacing a vaguely similar paragraph.',passage:'Mara took the bus to the hospital before dawn.',cardTitle:'An earlier version had a precise time.',kind:'Revision comparison',options:[['Restore the detail','At 5:10 a.m., Mara took the bus to the hospital.'],['Keep both','At 5:10 a.m., before dawn, Mara took the bus to the hospital.'],['Keep the broader wording','Mara took the bus to the hospital before dawn.']],signal:'After a revision removes a concrete detail; preferably on request or as a quiet comparison.',available:'Actual paragraph versions, sentence attempts, saved revisions, earlier folios and provenance.',needed:'Identify what was lost, verify it exists in a real revision, ask whether removal was intentional, and preview a span-level merge.',success:'The writer restores only what helps. In a real card, the earlier time must come from their saved text; this example is illustrative.'},
 {id:'next',name:'Choose a next step',hint:'Finish one small writing task',title:'Help the writer move once.',intent:'Replace a general motivational prompt with a short task grounded in this paragraph and its intended reader.',passage:'For the first time, the city felt open to people who worked through the night.',cardTitle:'What would let the reader see that?',kind:'A next step',options:[['Add an observed detail','Describe one place Mara could now reach.'],['Answer the reader','What did Mara have to do before the bus existed?'],['Leave a useful marker','[TK: add Mara’s journey before the night bus]']],signal:'An explicit request, or a strong pause-and-revision signal followed by confirmation that a next step is welcome.',available:'Current passage, reader/audience, goal, scraps, questions and existing way-in gates.',needed:'Task-specific prompts, a previewed insertion or saved marker, easy snooze, and a direct “did this help?” signal.',success:'The writer completes one task and returns to the draft. The card does not stay open merely to collect engagement.'}
];

const questions=[['timing','When should Twyne offer help without being asked?','For example: only after finishing a paragraph, after repeated revision, or on request.'],['judgement','What should happen when Jev cannot answer?','Should particular cards use a local fallback, wait, or offer an explicitly unassessed suggestion?'],['priorities','Which three interventions would you build first?','Choose by the writing problem they solve, rather than by how interesting the card looks.'],['focus','How should automatic quiet and manual Zen relate?','Should automatic focus only dim the workspace? Should help have its own independent switch?']];
const storageKey='twyne-decision-desk-review-v1';
let review={cards:{},answers:{}};
let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&typeof saved.cards==='object'&&saved.cards&&typeof saved.answers==='object'&&saved.answers)review=saved;}catch{storageAvailable=false;}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(review));storageAvailable=true;}catch{storageAvailable=false;}updateReviewCount();$('#save-status').textContent=storageAvailable?'Saved in this browser. Download your review to share it.':'Browser storage is unavailable. Your notes are held on this page; download them before leaving.';}
function updateReviewCount(){const n=Object.values(review.cards).filter(v=>v.vote||v.note||v.timing).length+Object.values(review.answers).filter(Boolean).length;$('#review-count').textContent=n;}
