function renderRanking(){const relevance=Number($('#relevance').value);$('#relevance-value').textContent=relevance.toFixed(2);const rows=rankDemo(relevance,$('#ranking-mode').value);$('#rank-results').innerHTML=rows.map(r=>`<div class="rank-row"><strong>${r.title}</strong><span>${r.score.toFixed(3)}</span><small>${r.visible?'Shown':'Held'} · ${esc(r.reason)}<div class="bar" style="width:${r.score/3*100}%"></div></small></div>`).join('');}
