function renderCard(id){const c=cards.find(x=>x.id===id)||cards[0];currentCard=c.id;const r=review.cards[c.id]||{};$('#card-buttons').innerHTML=cards.map(x=>`<button class="choice" data-card="${x.id}" aria-pressed="${x.id===c.id}">${x.name}<small>${x.hint}</small></button>`).join('');$('#proposal-detail').innerHTML=`<h2>${c.title}</h2><p class="proposal-intent">${c.intent}</p><div class="sample-desk"><div class="manuscript"><p class="meta">Illustrative manuscript</p><div id="sample-prose">${esc(c.passage).replace(/\n/g,'<br>')}</div><p class="preview-note" id="sample-status">Choose an option to preview it here.</p></div><div class="sample-card"><span class="label">${c.kind}</span><h3>${c.cardTitle}</h3>${c.diagram?'<div class="mini-map"><span>Bus before the first shift</span>↓<span>Hospital becomes reachable</span>↓<span class="missing">What explains the change?</span>↓<span>Fewer missed shifts</span></div>':''}${c.options.map(([label,body],i)=>`<button class="sample-option" data-option="${i}" aria-pressed="false"><strong>${label}</strong>${body}</button>`).join('')}<p class="preview-note">Illustrative options. No model request or document edit.</p></div></div><div class="proposal-spec">${[['When it could help',c.signal],['What we already have',c.available],['What needs building',c.needed],['How to judge usefulness',c.success]].map(([t,p])=>`<div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="feedback"><p class="feedback-title">Your verdict on “${c.name}”</p><div class="vote-buttons">${['Keep','Change','Drop'].map(v=>`<button data-vote="${v}" aria-pressed="${r.vote===v}">${v}</button>`).join('')}</div><label for="card-timing">When should this appear?</label><select id="card-timing"><option value="">Choose a timing preference</option>${['On request only','Offer after a pause','Offer at a paragraph boundary','Never automatically'].map(x=>`<option ${r.timing===x?'selected':''}>${x}</option>`).join('')}</select><label for="card-note">What would make this useful?</label><textarea id="card-note" placeholder="Change the trigger, the example, or the action…">${esc(r.note||'')}</textarea><p class="meta">Notes stay in this browser. Export them from Your review.</p></div>`;$('#card-timing').addEventListener('change',e=>{review.cards[c.id]={...review.cards[c.id],timing:e.target.value};save();});$('#card-note').addEventListener('input',e=>{review.cards[c.id]={...review.cards[c.id],note:e.target.value};save();});}

const sentences=['The city called the night bus a minor timetable change.','At 5:10 a.m., Mara stopped paying for a taxi to the hospital.','Within three months, missed shifts on the ward had fallen.','The council measured success in tickets sold.','The real change was who could afford to keep a job.','But a passenger count cannot show whether those journeys replaced taxis, walks, or trips never made.'];
const connections=[{id:'bridge',name:'A missing bridge',members:[1,2,4],title:'An experience, a pattern, a conclusion.',relation:'Example → possible evidence → conclusion',explanation:'Mara’s journey makes the benefit concrete. Fewer missed shifts could support the employment claim, but the draft has not established that the bus caused that change.',action:'Add the missing evidence, or narrow the conclusion.',suggestion:'Mara’s cheaper journey shows one benefit of the route. Whether it also reduced missed shifts needs evidence beyond the change in timing.',question:'What would establish the relationship between the bus route and attendance?',preview:'Mara’s cheaper journey shows one benefit of the route. Whether it also reduced missed shifts needs evidence beyond the change in timing.'},{id:'measures',name:'Two different measures',members:[3,4,5],title:'The metric and the meaning diverge.',relation:'Metric → intended outcome → limitation',explanation:'Ticket sales measure use. Keeping a job is the outcome you care about. Your final sentence already identifies why the metric cannot fully answer the claim.',action:'Put the limitation beside the metric.',suggestion:'Bring the final sentence next to the council’s measure, then ask what would capture the effect on workers.',question:'Which measure would actually test the argument you are making?',preview:'The council measured success in tickets sold. But a passenger count cannot show whether those journeys replaced taxis, walks, or trips never made.'},{id:'return',name:'An opening answered',members:[0,4],title:'“Minor” becomes the argument’s hinge.',relation:'Opening frame → later reappraisal',explanation:'Your later conclusion answers the city’s dismissive opening. Making that contrast deliberate could give the piece a stronger structure without adding a new idea.',action:'Use the opening as a deliberate return.',suggestion:'The timetable change was minor on paper. For workers like Mara, the question was whether it made