$('#connection-sentences').innerHTML=sentences.map((s,i)=>`<button class="sentence" data-sentence="${i}" aria-describedby="connection-explanation"><span class="sentence-number">${i+1}</span><span>${s}</span></button>`).join('');
function renderConnection(id){const c=connections.find(x=>x.id===id)||connections[0];currentConnection=c.id;$('#connection-buttons').innerHTML=connections.map(x=>`<button data-connection="${x.id}" aria-pressed="${x.id===c.id}">${x.name}</button>`).join('');$$('.sentence').forEach((el,i)=>{el.classList.toggle('linked',c.members.includes(i));el.setAttribute('aria-pressed',String(c.members.includes(i)));});$('#connection-explanation').innerHTML=`<span class="label">Sentences ${c.members.map(n=>n+1).join(' + ')}</span><h2>${c.title}</h2><p class="relation">${c.relation}</p><p>${c.explanation}</p><div class="connection-advice"><h3>${c.action}</h3><p>${c.suggestion}</p><button class="primary" id="preview-bridge">Preview this suggestion</button><div id="bridge-preview" hidden><p>${c.preview}</p><span class="meta">Preview only. The illustrative draft remains above.</span></div></div><p class="meta">A question for the writer: ${c.question}</p>`;$('#preview-bridge').addEventListener('click',()=>{$('#bridge-preview').hidden=!$('#bridge-preview').hidden;$('#preview-bridge').textContent=$('#bridge-preview').hidden?'Preview this suggestion':'Hide the preview';});requestAnimationFrame(drawConnections);}
function drawConnections(){if($('#connections').hidden)return;const c=connections.find(x=>x.id===currentConnection),parent=$('#connection-manuscript'),box=parent.getBoundingClientRect(),svg=$('#connection-lines');svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);const rects=c.members.map(i=>$(`[data-sentence="${i}"]`).getBoundingClientRect());const x=box.width-34;svg.innerHTML=rects.slice(1).map((r,i)=>{const a=rects[i].top+rects[i].height/2-box.top,b=r.top+r.height/2-box.top;return `<path d="M ${x} ${a} C ${box.width-4} ${a}, ${box.width-4} ${b}, ${x} ${b}"/><circle cx="${x}" cy="${a}" r="3"/><circle cx="${x}" cy="${b}" r="3"/>`;}).join('');}
function activateSentence(i){const existing=connections.find(c=>c.id===currentConnection);if(!existing.members.includes(i)){const c=connections.find(c=>c.members.includes(i));if(c)renderConnection(c.id);}}
$$('.sentence').forEach(el=>{el.addEventListener('pointerenter',()=>activateSentence(Number(el.dataset.sentence)));el.addEventListener('focus',()=>activateSentence(Number(el.dataset.sentence)));el.addEventListener('click',()=>activateSentence(Number(el.dataset.sentence)));});
