  }
  const gitDirectory = (await git(["rev-parse", "--absolute-git-dir"])).stdout.trim();
  if (["MERGE_HEAD", "CHERRY_PICK_HEAD", "REVERT_HEAD", "rebase-merge", "rebase-apply"].some((name) => existsSync(path.join(gitDirectory, name)))) {
